1	package com.example.starter.batch;
2	
3	import com.example.starter.batch.dto.ApprovalResponse;
4	import com.example.starter.batch.dto.ApproveRequest;
5	import com.example.starter.batch.dto.BatchHistoryResponse;
6	import com.example.starter.batch.dto.BatchResponse;
7	import com.example.starter.batch.dto.CreateBatchRequest;
8	import com.example.starter.batch.dto.LineageEntryResponse;
9	import com.example.starter.batch.dto.RecallRequest;
10	import com.example.starter.batch.dto.RecallResponse;
11	import com.example.starter.batch.dto.SplitRequest;
12	import com.example.starter.batch.dto.SplitResponse;
13	import com.example.starter.batch.dto.SubmitTestRequest;
14	import com.example.starter.batch.dto.TestResultResponse;
15	import com.fasterxml.jackson.core.JsonProcessingException;
16	import com.fasterxml.jackson.databind.ObjectMapper;
17	import org.springframework.dao.DuplicateKeyException;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.PlatformTransactionManager;
20	import org.springframework.transaction.support.TransactionTemplate;
21	
22	import java.nio.charset.StandardCharsets;
23	import java.security.MessageDigest;
24	import java.security.NoSuchAlgorithmException;
25	import java.time.Instant;
26	import java.util.ArrayDeque;
27	import java.util.ArrayList;
28	import java.util.Collections;
29	import java.util.Deque;
30	import java.util.HashMap;
31	import java.util.HashSet;
32	import java.util.List;
33	import java.util.Map;
34	import java.util.Optional;
35	import java.util.Set;
36	import java.util.function.Supplier;
37	
38	/**
39	 * 批次隔离与放行核心服务。
40	 *
41	 * <p>并发策略：同一批次的检验/批准/召回在事务内对 batch 行 SELECT ... FOR UPDATE 串行化，
42	 * 按事务提交顺序生效；commandKey 幂等通过 command_log 主键 + 参数指纹实现，
43	 * 同键同参重放返回首次响应快照，同键改参返回 409；仅成功命令写入 command_log。
44	 */
45	@Service
46	public class BatchService {
47	
48	    private static final String CMD_CREATE = "CREATE_BATCH";
49	    private static final String CMD_TEST = "SUBMIT_TEST";
50	    private static final String CMD_APPROVE = "APPROVE";
51	    private static final String CMD_RECALL = "RECALL";
52	    private static final String CMD_SPLIT = "SPLIT";
53	
54	    /**
55	     * 指纹拼接分隔符（NUL）：业务参数不可能包含该字符，避免拼接碰撞。
56	     */
57	    private static final String SEP = "\u0000";
58	
59	    private static final int IDEMPOTENCY_MAX_ATTEMPTS = 3;
60	
61	    private final BatchRepository repo;
62	    private final TransactionTemplate tx;
63	    private final ObjectMapper objectMapper;
64	
65	    public BatchService(BatchRepository repo,
66	                        PlatformTransactionManager transactionManager,
67	                        ObjectMapper objectMapper) {
68	        this.repo = repo;
69	        this.tx = new TransactionTemplate(transactionManager);
70	        this.objectMapper = objectMapper;
71	    }
72	
73	    /**
74	     * 创建批次：初始状态 QUARANTINED；batchKey 全局唯一，重复返回 409。
75	     */
76	    public StoredResponse createBatch(CreateBatchRequest req) {
77	        List<String> items = req.requiredTests().stream().map(String::trim).toList();
78	        if (new HashSet<>(items).size() != items.size()) {
79	            throw ApiException.badRequest("requiredTests 存在重复检验项");
80	        }
81	        String fingerprint = fingerprint("create", req.batchKey(), req.productCode(), req.batchNo(),
82	                req.producedAt().toString(), String.join(SEP, items));
83	        return executeIdempotent(CMD_CREATE, req.commandKey(), fingerprint, () -> {
84	            repo.findBatch(req.batchKey()).ifPresent(b -> {
85	                throw ApiException.conflict("batchKey 已存在: " + req.batchKey());
86	            });
87	            String now = now();
88	            repo.insertBatch(new BatchRepository.BatchRow(0L, req.batchKey(), req.productCode(),
89	                    req.batchNo(), req.producedAt().toString(), BatchStatus.QUARANTINED.name(), now));
90	            for (int i = 0; i < items.size(); i++) {
91	                repo.insertRequiredTest(req.batchKey(), items.get(i), i + 1);
92	            }
93	            BatchResponse body = new BatchResponse(req.batchKey(), req.productCode(), req.batchNo(),
94	                    req.producedAt(), BatchStatus.QUARANTINED, items, Instant.parse(now));
95	            return new StoredResponse(201, toJson(body));
96	        });
97	    }
98	
99	    /**
100	     * 提交检验结果：testKey 批次内幂等；任一 FAIL 立即 REJECTED；全部必做项 PASS 后 PENDING_RELEASE。
101	     */
102	    public StoredResponse submitTest(String batchKey, SubmitTestRequest req) {
103	        String fingerprint = fingerprint("test", batchKey, req.testKey(), req.testItem(),
104	                req.result().name(), req.inspector());
105	        return executeIdempotent(CMD_TEST, req.commandKey(), fingerprint, () -> {
106	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
107	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
108	
109	            var existing = repo.findTest(batchKey, req.testKey());
110	            if (existing.isPresent()) {
111	                BatchRepository.TestRow row = existing.get();
112	                boolean sameContent = row.testItem().equals(req.testItem())
113	                        && row.outcome().equals(req.result().name())
114	                        && row.inspector().equals(req.inspector());
115	                if (!sameContent) {
116	                    throw ApiException.conflict("testKey 已以不同内容提交: " + req.testKey());
117	                }
118	                List<String> required = repo.findRequiredTests(batchKey);
119	                BatchStatus snapshot = snapshotAfter(row, repo.findTests(batchKey), required);
120	                return new StoredResponse(200, toJson(toTestResponse(row, snapshot.name())));
121	            }
122	
123	            BatchStatus status = BatchStatus.valueOf(batch.status());
124	            assertNoRecalledAncestor(batchKey);
125	            if (status == BatchStatus.REJECTED || status == BatchStatus.RELEASED
126	                    || status == BatchStatus.RECALLED || status == BatchStatus.SPLIT) {
127	                throw ApiException.conflict("批次状态 " + status + " 不允许提交检验");
128	            }
129	            List<String> required = repo.findRequiredTests(batchKey);
130	            if (!required.contains(req.testItem())) {
131	                throw ApiException.unprocessable("检验项不属于该批次必做项: " + req.testItem());
132	            }
133	            boolean itemAlreadyTested = repo.findTests(batchKey).stream()
134	                    .anyMatch(t -> t.testItem().equals(req.testItem()));
135	            if (itemAlreadyTested) {
136	                throw ApiException.conflict("该检验项已存在检验结果: " + req.testItem());
137	            }
138	
139	            String now = now();
140	            repo.insertTest(new BatchRepository.TestRow(0L, batchKey, req.testKey(), req.testItem(),
141	                    req.result().name(), req.inspector(), now));
142	
143	            BatchStatus newStatus = status;
144	            if (req.result() == TestOutcome.FAIL) {
145	                newStatus = BatchStatus.REJECTED;
146	            } else if (status == BatchStatus.QUARANTINED && allRequiredPassed(batchKey, required)) {
147	                newStatus = BatchStatus.PENDING_RELEASE;
148	            }
149	            if (newStatus != status) {
150	                repo.updateStatus(batchKey, newStatus.name());
151	            }
152	            TestResultResponse body = new TestResultResponse(batchKey, req.testKey(), req.testItem(),
153	                    req.result(), req.inspector(), newStatus, Instant.parse(now));
154	            return new StoredResponse(201, toJson(body));
155	        });
156	    }
157	
158	    /**
159	     * 批准：两步放行。首个有效批准进入 RELEASE_REVIEW，第二个不同角色、不同批准人批准后 RELEASED。
160	     */
161	    public StoredResponse approve(String batchKey, String actorId, String roleHeader, ApproveRequest req) {
162	        if (actorId == null || actorId.isBlank()) {
163	            throw ApiException.badRequest("X-Actor-Id 不能为空");
164	        }
165	        ApprovalRole role = parseRole(roleHeader);
166	        String actor = actorId.trim();
167	        String fingerprint = fingerprint("approve", batchKey, actor, role.name());
168	        return executeIdempotent(CMD_APPROVE, req.commandKey(), fingerprint, () -> {
169	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
170	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
171	            BatchStatus status = BatchStatus.valueOf(batch.status());
172	            assertNoRecalledAncestor(batchKey);
173	            if (status == BatchStatus.QUARANTINED) {
174	                throw ApiException.unprocessable("必做检验项未全部通过，不能批准");
175	            }
176	            if (status != BatchStatus.PENDING_RELEASE && status != BatchStatus.RELEASE_REVIEW) {
177	                throw ApiException.conflict("批次状态 " + status + " 不允许批准");
178	            }
179	            boolean actorInspected = repo.findTests(batchKey).stream()
180	                    .anyMatch(t -> t.inspector().equals(actor));
181	            if (actorInspected) {
182	                throw ApiException.unprocessable("批准人不得为该批次任一检验结果的检验人: " + actor);
183	            }
184	
185	            List<BatchRepository.ApprovalRow> approvals = repo.findApprovals(batchKey);
186	            String now = now();
187	            int seq;
188	            BatchStatus newStatus;
189	            if (approvals.isEmpty()) {
190	                seq = 1;
191	                newStatus = BatchStatus.RELEASE_REVIEW;
192	            } else {
193	                BatchRepository.ApprovalRow first = approvals.get(0);
194	                if (first.role().equals(role.name())) {
195	                    throw ApiException.conflict("角色 " + role + " 已批准过，需要另一种角色");
196	                }
197	                if (first.actorId().equals(actor)) {
198	                    throw ApiException.conflict("两个批准人必须不同: " + actor);
199	                }
200	                seq = 2;
201	                newStatus = BatchStatus.RELEASED;
202	            }
203	            repo.insertApproval(new BatchRepository.ApprovalRow(0L, batchKey, req.commandKey(),
204	                    actor, role.name(), seq, now));
205	            repo.updateStatus(batchKey, newStatus.name());
206	            ApprovalResponse body = new ApprovalResponse(batchKey, actor, role, seq, newStatus,
207	                    Instant.parse(now));
208	            return new StoredResponse(201, toJson(body));
209	        });
210	    }
211	
212	    /**
213	     * 召回：RELEASED 或 SPLIT 批次可召回，召回后进入 RECALLED 并不再出现在可用批次查询中。
214	     * 召回提交后其全部后代立即不可用（排除出可用查询、禁止新增检验/批准/拆分），
215	     * 但后代自身状态与既有检验、批准记录不改写，也不为后代补写召回记录。
216	     */
217	    public StoredResponse recall(String batchKey, String actorId, RecallRequest req) {
218	        if (actorId == null || actorId.isBlank()) {
219	            throw ApiException.badRequest("X-Actor-Id 不能为空");
220	        }
221	        String actor = actorId.trim();
222	        String fingerprint = fingerprint("recall", batchKey, actor, req.reason());
223	        return executeIdempotent(CMD_RECALL, req.commandKey(), fingerprint, () -> {
224	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
225	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
226	            BatchStatus status = BatchStatus.valueOf(batch.status());
227	            if (status != BatchStatus.RELEASED && status != BatchStatus.SPLIT) {
228	                throw ApiException.conflict("批次状态 " + status + " 不允许召回，仅 RELEASED 或 SPLIT 可召回");
229	            }
230	            // 逐行锁定全部后代（按业务键排序保证锁顺序确定）：与后代上的检验/批准/拆分
231	            // 互斥，按事务提交顺序裁决——召回先提交则后代新操作看到召回并返回 422。
232	            List<String> descendants = descendantKeys(batchKey);
233	            Collections.sort(descendants);
234	            for (String descendantKey : descendants) {
235	                repo.findBatchForUpdate(descendantKey);
236	            }
237	            String now = now();
238	            repo.insertRecall(new BatchRepository.RecallRow(0L, batchKey, req.commandKey(),
239	                    actor, req.reason(), now));
240	            repo.updateStatus(batchKey, BatchStatus.RECALLED.name());
241	            RecallResponse body = new RecallResponse(batchKey, actor, req.reason(),
242	                    BatchStatus.RECALLED, Instant.parse(now));
243	            return new StoredResponse(201, toJson(body));
244	        });
245	    }
246	
247	    /**
248	     * 当前可用批次：排除已召回（RECALLED）、已拆分（SPLIT）批次，
249	     * 以及任一祖先被召回的后代批次；后代自身状态不改写。
250	     */
251	    public List<BatchResponse> listAvailable() {
252	        Map<String, String> parentOf = childToParent();
253	        Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
254	        return repo.findAvailableBatches().stream()
255	                .filter(b -> !BatchStatus.SPLIT.name().equals(b.status()))
256	                .filter(b -> recalledAncestor(b.batchKey(), parentOf, recalled).isEmpty())
257	                .map(this::toBatchResponse)
258	                .toList();
259	    }
260	
261	    /**
262	     * 批次完整历史：批次概要 + 全部检验 + 全部批准 + 召回记录，历史不因召回而删除或改写。
263	     */
264	    public BatchHistoryResponse history(String batchKey) {
265	        BatchRepository.BatchRow batch = repo.findBatch(batchKey)
266	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
267	        List<String> required = repo.findRequiredTests(batchKey);
268	        List<BatchRepository.TestRow> testRows = repo.findTests(batchKey);
269	        // 按提交顺序推导每条检验结果落定后的批次状态快照：FAIL→REJECTED；
270	        // 必做项全部 PASS 时该条→PENDING_RELEASE；其余→QUARANTINED。
271	        List<TestResultResponse> tests = new java.util.ArrayList<>(testRows.size());
272	        for (BatchRepository.TestRow t : testRows) {
273	            tests.add(toTestResponse(t, snapshotAfter(t, testRows, required).name()));
274	        }
275	        List<ApprovalResponse> approvals = repo.findApprovals(batchKey).stream()
276	                .map(a -> {
277	                    // 历史快照：第一笔批准落定 RELEASE_REVIEW，第二笔落定 RELEASED；不随后续召回改写
278	                    BatchStatus snapshot = a.seq() == 1
279	                            ? BatchStatus.RELEASE_REVIEW
280	                            : BatchStatus.RELEASED;
281	                    return new ApprovalResponse(a.batchKey(), a.actorId(), ApprovalRole.valueOf(a.role()),
282	                            a.seq(), snapshot, Instant.parse(a.createdAt()));
283	                })
284	                .toList();
285	        RecallResponse recall = repo.findRecall(batchKey)
286	                .map(r -> new RecallResponse(r.batchKey(), r.actorId(), r.reason(),
287	                        BatchStatus.RECALLED, Instant.parse(r.createdAt())))
288	                .orElse(null);
289	        return new BatchHistoryResponse(toBatchResponse(batch), tests, approvals, recall);
290	    }
291	
292	    /**
293	     * 幂等执行：同事务内先查 command_log，命中则按指纹返回快照或 409；
294	     * 未命中执行业务动作并写入快照。并发同键插入冲突时重试，读取已提交结果。
295	     */
296	    private StoredResponse executeIdempotent(String type, String commandKey, String fingerprint,
297	                                             Supplier<StoredResponse> action) {
298	        for (int attempt = 0; attempt < IDEMPOTENCY_MAX_ATTEMPTS; attempt++) {
299	            try {
300	                return tx.execute(status -> {
301	                    var logged = loggedResponse(type, commandKey, fingerprint);
302	                    if (logged.isPresent()) {
303	                        return logged.get();
304	                    }
305	                    StoredResponse response = action.get();
306	                    repo.insertCommand(new BatchRepository.CommandRow(type, commandKey, fingerprint,
307	                            response.status(), response.body()), now());
308	                    return response;
309	                });
310	            } catch (DuplicateKeyException e) {
311	                // 并发同事务键冲突：回滚后重试，读取对方已提交的命令快照或业务结果
312	            }
313	        }
314	        throw ApiException.conflict("命令并发冲突，请重试: " + commandKey);
315	    }
316	
317	    /**
318	     * 查询命令快照：命中且指纹一致返回首次响应；指纹不一致抛 409；未命中返回空。
319	     */
320	    private Optional<StoredResponse> loggedResponse(String type, String commandKey,
321	                                                    String fingerprint) {
322	        var existing = repo.findCommand(type, commandKey);
323	        if (existing.isEmpty()) {
324	            return Optional.empty();
325	        }
326	        BatchRepository.CommandRow row = existing.get();
327	        if (!row.fingerprint().equals(fingerprint)) {
328	            throw ApiException.conflict("commandKey 已以不同参数使用: " + commandKey);
329	        }
330	        return Optional.of(new StoredResponse(row.responseStatus(), row.responseBody()));
331	    }
332	
333	    private boolean allRequiredPassed(String batchKey, List<String> required) {
334	        Set<String> passed = new HashSet<>();
335	        for (BatchRepository.TestRow t : repo.findTests(batchKey)) {
336	            if (TestOutcome.PASS.name().equals(t.outcome())) {
337	                passed.add(t.testItem());
338	            }
339	        }
340	        return passed.containsAll(required);
341	    }
342	
343	    private BatchResponse toBatchResponse(BatchRepository.BatchRow row) {
344	        return new BatchResponse(row.batchKey(), row.productCode(), row.batchNo(),
345	                Instant.parse(row.producedAt()), BatchStatus.valueOf(row.status()),
346	                repo.findRequiredTests(row.batchKey()), Instant.parse(row.createdAt()));
347	    }
348	
349	    private TestResultResponse toTestResponse(BatchRepository.TestRow row, String batchStatus) {
350	        return new TestResultResponse(row.batchKey(), row.testKey(), row.testItem(),
351	                TestOutcome.valueOf(row.outcome()), row.inspector(),
352	                BatchStatus.valueOf(batchStatus), Instant.parse(row.createdAt()));
353	    }
354	
355	    /**
356	     * 推导某条检验结果提交落定后的批次状态快照（按检验结果提交顺序）：
357	     * FAIL→REJECTED；此前已有 PASS 已覆盖全部必做项→PENDING_RELEASE；其余→QUARANTINED。
358	     */
359	    private BatchStatus snapshotAfter(BatchRepository.TestRow target,
360	                                      List<BatchRepository.TestRow> ordered,
361	                                      List<String> required) {
362	        if (TestOutcome.FAIL.name().equals(target.outcome())) {
363	            return BatchStatus.REJECTED;
364	        }
365	        Set<String> passed = new HashSet<>();
366	        for (BatchRepository.TestRow t : ordered) {
367	            if (TestOutcome.PASS.name().equals(t.outcome())) {
368	                passed.add(t.testItem());
369	            }
370	            if (t.id() == target.id()) {
371	                break;
372	            }
373	        }
374	        return passed.containsAll(required)
375	                ? BatchStatus.PENDING_RELEASE
376	                : BatchStatus.QUARANTINED;
377	    }
378	
379	    private ApprovalRole parseRole(String roleHeader) {
380	        if (roleHeader == null || roleHeader.isBlank()) {
381	            throw ApiException.badRequest("X-Approval-Role 不能为空");
382	        }
383	        try {
384	            return ApprovalRole.valueOf(roleHeader.trim());
385	        } catch (IllegalArgumentException e) {
386	            throw ApiException.badRequest("X-Approval-Role 必须为 QUALITY 或 OPERATIONS");
387	        }
388	    }
389	
390	    private String toJson(Object body) {
391	        try {
392	            return objectMapper.writeValueAsString(body);
393	        } catch (JsonProcessingException e) {
394	            throw new IllegalStateException("响应序列化失败", e);
395	        }
396	    }
397	
398	    private String now() {
399	        return Instant.now().toString();
400	    }
401	
402	    private String fingerprint(String... parts) {        String canonical = String.join(SEP, parts);
403	        try {
404	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
405	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
406	            StringBuilder hex = new StringBuilder(hash.length * 2);
407	            for (byte b : hash) {
408	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
409	                hex.append(Character.forDigit(b & 0xF, 16));
410	            }
411	            return hex.toString();
412	        } catch (NoSuchAlgorithmException e) {
413	            throw new IllegalStateException("SHA-256 不可用", e);
414	        }
415	    }
416	
417	    /**
418	     * 拆分：仅当前可用的 RELEASED 批次可一次拆成 2～5 个全新子批。
419	     * 子批继承产品编码、生产 UTC 时间与必做检验项，初始 QUARANTINED，
420	     * 不继承检验或批准记录；父批置为 SPLIT 不再可用。
421	     * 创建全部子批、血缘关系与父批状态在同一事务提交；任一子批键已存在或重复，整次 409 且父批不变。
422	     */
423	    public StoredResponse split(String parentKey, SplitRequest req) {
424	        List<SplitRequest.ChildSpec> children = req.children();
425	        List<String> childKeys = children.stream().map(SplitRequest.ChildSpec::batchKey).toList();
426	        if (new HashSet<>(childKeys).size() != childKeys.size()) {
427	            throw ApiException.conflict("子批 batchKey 在请求内重复");
428	        }
429	        List<String> parts = new ArrayList<>();
430	        parts.add("split");
431	        parts.add(parentKey);
432	        for (SplitRequest.ChildSpec child : children) {
433	            parts.add(child.batchKey());
434	            parts.add(child.batchNo());
435	        }
436	        String fingerprint = fingerprint(parts.toArray(new String[0]));
437	        return executeIdempotent(CMD_SPLIT, req.commandKey(), fingerprint, () -> {
438	            BatchRepository.BatchRow parent = repo.findBatchForUpdate(parentKey)
439	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + parentKey));
440	            // 父批行锁后重查命令快照：并发同键请求在锁等待期间可能已由对方提交，
441	            // 此时须重放首次结果而不是因父批已 SPLIT 误判冲突
442	            var logged = loggedResponse(CMD_SPLIT, req.commandKey(), fingerprint);
443	            if (logged.isPresent()) {
444	                return logged.get();
445	            }
446	            assertNoRecalledAncestor(parentKey);
447	            if (!BatchStatus.RELEASED.name().equals(parent.status())) {
448	                throw ApiException.conflict(
449	                        "批次状态 " + parent.status() + " 不允许拆分，仅当前可用的 RELEASED 批次可拆分");
450	            }
451	            for (String childKey : childKeys) {
452	                if (repo.findBatch(childKey).isPresent()) {
453	                    throw ApiException.conflict("子批 batchKey 已存在: " + childKey);
454	                }
455	            }
456	            String now = now();
457	            List<String> required = repo.findRequiredTests(parentKey);
458	            List<SplitResponse.SplitChild> childBodies = new ArrayList<>(children.size());
459	            for (int i = 0; i < children.size(); i++) {
460	                SplitRequest.ChildSpec spec = children.get(i);
461	                repo.insertBatch(new BatchRepository.BatchRow(0L, spec.batchKey(), parent.productCode(),
462	                        spec.batchNo(), parent.producedAt(), BatchStatus.QUARANTINED.name(), now));
463	                for (int j = 0; j < required.size(); j++) {
464	                    repo.insertRequiredTest(spec.batchKey(), required.get(j), j + 1);
465	                }
466	                repo.insertLineage(new BatchRepository.LineageRow(0L, parentKey, spec.batchKey(),
467	                        i + 1, now));
468	                childBodies.add(new SplitResponse.SplitChild(spec.batchKey(), spec.batchNo(),
469	                        parent.productCode(), Instant.parse(parent.producedAt()),
470	                        BatchStatus.QUARANTINED, required, Instant.parse(now)));
471	            }
472	            repo.updateStatus(parentKey, BatchStatus.SPLIT.name());
473	            SplitResponse body = new SplitResponse(parentKey, BatchStatus.SPLIT, childBodies,
474	                    Instant.parse(now));
475	            return new StoredResponse(201, toJson(body));
476	        });
477	    }
478	
479	    /**
480	     * 祖先查询：从直接父批逐级向上到根，每项含批次自身状态及导致其不可用的召回祖先。
481	     */
482	    public List<LineageEntryResponse> listAncestors(String batchKey) {
483	        repo.findBatch(batchKey)
484	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
485	        Map<String, String> parentOf = childToParent();
486	        Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
487	        List<LineageEntryResponse> result = new ArrayList<>();
488	        String current = batchKey;
489	        while (parentOf.containsKey(current)) {
490	            current = parentOf.get(current);
491	            result.add(toLineageEntry(current, parentOf, recalled));
492	        }
493	        return result;
494	    }
495	
496	    /**
497	     * 后代查询：按血缘关系创建顺序广度优先展开，每项含批次自身状态及导致其不可用的召回祖先。
498	     */
499	    public List<LineageEntryResponse> listDescendants(String batchKey) {
500	        repo.findBatch(batchKey)
501	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
502	        Map<String, String> parentOf = childToParent();
503	        Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
504	        List<LineageEntryResponse> result = new ArrayList<>();
505	        for (String key : descendantKeys(batchKey)) {
506	            result.add(toLineageEntry(key, parentOf, recalled));
507	        }
508	        return result;
509	    }
510	
511	    /**
512	     * 若任一级祖先已被召回则抛 422：后代批次禁止新增检验、批准和拆分。
513	     */
514	    private void assertNoRecalledAncestor(String batchKey) {
515	        Optional<String> recalled = recalledAncestor(batchKey, childToParent(),
516	                new HashSet<>(repo.findRecalledKeys()));
517	        if (recalled.isPresent()) {
518	            throw ApiException.unprocessable(
519	                    "祖先批次 " + recalled.get() + " 已召回，禁止新增检验、批准和拆分");
520	        }
521	    }
522	
523	    /**
524	     * 沿父链向上查找最近的被直接召回（RECALLED）祖先；批次自身召回不算祖先召回。
525	     */
526	    private Optional<String> recalledAncestor(String batchKey, Map<String, String> parentOf,
527	                                              Set<String> recalled) {
528	        String current = batchKey;
529	        while (parentOf.containsKey(current)) {
530	            current = parentOf.get(current);
531	            if (recalled.contains(current)) {
532	                return Optional.of(current);
533	            }
534	        }
535	        return Optional.empty();
536	    }
537	
538	    /**
539	     * 全部血缘边的 子批→父批 映射；关系不可改写，只增不改。
540	     */
541	    private Map<String, String> childToParent() {
542	        Map<String, String> parentOf = new HashMap<>();
543	        for (BatchRepository.LineageRow row : repo.findAllLineage()) {
544	            parentOf.put(row.childKey(), row.parentKey());
545	        }
546	        return parentOf;
547	    }
548	
549	    /**
550	     * 某批次的全部后代业务键，按血缘关系创建顺序广度优先展开（不含自身）。
551	     */
552	    private List<String> descendantKeys(String rootKey) {
553	        Map<String, List<String>> childrenOf = new HashMap<>();
554	        for (BatchRepository.LineageRow row : repo.findAllLineage()) {
555	            childrenOf.computeIfAbsent(row.parentKey(), k -> new ArrayList<>()).add(row.childKey());
556	        }
557	        List<String> result = new ArrayList<>();
558	        Deque<String> queue = new ArrayDeque<>();
559	        queue.add(rootKey);
560	        while (!queue.isEmpty()) {
561	            String current = queue.poll();
562	            for (String child : childrenOf.getOrDefault(current, List.of())) {
563	                result.add(child);
564	                queue.add(child);
565	            }
566	        }
567	        return result;
568	    }
569	
570	    private LineageEntryResponse toLineageEntry(String batchKey, Map<String, String> parentOf,
571	                                                Set<String> recalled) {
572	        BatchRepository.BatchRow row = repo.findBatch(batchKey)
573	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
574	        return new LineageEntryResponse(row.batchKey(), row.batchNo(),
575	                BatchStatus.valueOf(row.status()),
576	                recalledAncestor(batchKey, parentOf, recalled).orElse(null));
577	    }
578	}
