402	    void concurrentRecallAndFinalApproval_cannotReleaseAfterRecall() throws Exception {
403	        String batchKey = "BK-RACE-RC-" + unique();
404	        createBatch(batchKey, List.of("t1"), 201);
405	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp"), null, null, 201);
406	        approve(batchKey, "qa", "QUALITY", "CK-Q", 201);
407	
408	        List<Future<Integer>> results = runConcurrent(
409	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
410	                        .header("X-Actor-Id", "ops").header("X-Approval-Role", "OPERATIONS")
411	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CK-O\"}")),
412	                () -> callStatus(post("/api/batches/" + batchKey + "/recall")
413	                        .header("X-Actor-Id", "u")
414	                        .contentType(MediaType.APPLICATION_JSON)
415	                        .content("{\"commandKey\":\"CK-R\",\"reason\":\"临检异常\"}"))
416	        );
417	
418	        int secondApproval = results.get(0).get(30, TimeUnit.SECONDS);
419	        int recall = results.get(1).get(30, TimeUnit.SECONDS);
420	        String finalStatus = currentStatus(batchKey);
421	        Integer recallRows = jdbc.queryForObject(
422	                "SELECT COUNT(*) FROM recall WHERE batch_key = ?", Integer.class, batchKey);
423	        if (recallRows > 0) {
424	            // 第二批准先提交为 RELEASED，召回随后提交：终态 RECALLED，绝不可能再被放行
425	            assertEquals(201, secondApproval);
426	            assertEquals(201, recall);
427	            assertEquals("RECALLED", finalStatus);
428	        } else {
429	            // 召回在 RELEASE_REVIEW 阶段先获锁被拒，第二批准随后提交：终态 RELEASED，无召回记录
430	            assertEquals(409, recall);
431	            assertEquals(201, secondApproval);
432	            assertEquals("RELEASED", finalStatus);
433	        }
434	        // 批准历史始终可查，未被召回删除
435	        Integer approvals = jdbc.queryForObject(
436	                "SELECT COUNT(*) FROM approval WHERE batch_key = ?", Integer.class, batchKey);
437	        assertTrue(approvals >= 1);
438	    }
