private BatchStatus recomputeAssayStatus(String batchKey, BatchStatus current) {
    List<String> required = repo.findRequiredTests(batchKey);
    if (!allRequiredPassed(batchKey, required)) return BatchStatus.QUARANTINED;
    int valid = repo.findValidApprovals(batchKey).size();
    if (valid >= 2) return BatchStatus.RELEASED;
    if (valid == 1) return BatchStatus.RELEASE_REVIEW;
    return BatchStatus.PENDING_RELEASE;
}
