public StoredResponse writeAssayReading(String batchKey, String actorId, WriteAssayReadingRequest req) {
    String actor = requireActor(actorId);
    String fingerprint = structuredFingerprint("assay.read", actor, batchKey, req.testItem(),
            "seq", String.valueOf(req.seq()), "value", req.value(),
            "expectedVersion", String.valueOf(req.expectedVersion()));
    return executeIdempotent(CMD_WRITE_READING, req.requestId(), fingerprint, () -> {
        BatchRow batch = repo.findBatchForUpdate(batchKey).orElseThrow(notFound);
        BatchStatus status = valueOf;
        assertNoRecalledAncestor(batchKey);
        if (status == REJECTED || RELEASED || RECALLED || SPLIT) throw conflict("批次状态 ... 不允许写读数");
        List<AssayRoundRow> rounds = repo.findAssayRounds(batchKey, req.testItem());
        if (rounds.isEmpty()) throw conflict("该检验项不存在平行测定轮次");
        AssayRoundRow current = last;
        if (!ROUND_OPEN.equals(current.status())) throw conflict("当前轮次已封结，不能覆写");
        if (current.version() != req.expectedVersion()) throw conflict("expectedVersion 不符: 期望 " + req.expectedVersion() + " 当前 " + current.version());
        // seq 唯一
        List<AssayReadingRow> readings = repo.findAssayReadings(current.id());
        if (readings.stream().anyMatch(r -> r.seq() == req.seq())) throw conflict("读数序号已写入: " + req.seq());
        String now = now();
        repo.insertAssayReading(new AssayReadingRow(0, current.id(), batchKey, req.testItem(), req.seq(), req.value(), actor, now));
        int newVersion = current.version() + 1;
        AssayRoundRow updated = current;
        if (newVersion >= READINGS_PER_ROUND) {
            // 封结判定
            List<BigDecimal> values = readings+new ... map BigDecimal
            BigDecimal sum; mean = sum.divide(BigDecimal.valueOf(3), MathContext.DECIMAL128);
            BigDecimal max, min; range = max.subtract(min);
            boolean passed = mean.compareTo(new BigDecimal(current.meanMin())) >= 0
                && mean.compareTo(new BigDecimal(current.meanMax())) <= 0
                && range.compareTo(new BigDecimal(current.maxRange())) <= 0;
            String sealStatus = passed ? ROUND_PASSED : ROUND_FAILED;
            repo.sealAssayRound(current.id(), sealStatus, newVersion, mean.stripTrailingZeros().toPlainString(), range.stripTrailingZeros().toPlainString(), now);
            updated = new AssayRoundRow(current.id(), ..., sealStatus, newVersion, mean..., range..., ...);
        } else {
            repo.bumpAssayRoundVersion(current.id(), newVersion);
            updated = ... version newVersion;
        }
        BatchStatus newStatus = status;
        if (sealed && passed) {
            newStatus = recomputeAssayStatus(batchKey, status);
            if (newStatus != status) repo.updateStatus(...);
        }
        body = toAssayRoundResponse(updated, newStatus);
        return new StoredResponse(201, toJson(body));
    });
}
